import {createIcons,icons} from 'lucide';
import {grokBotSVG,finishForIdentity} from './bot-art.js';
import {templates,templateHTML} from './templates.js';
import {allCreationsEntries,publicCreationsEntries} from './creations.js';
import {launchCard,mergePublicLaunches} from './token-gallery.js';
import {escapeHTML as esc,sandboxHTML,validateToken,solToLamports} from './shared.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icon=n=>`<i data-lucide="${n}"></i>`;
const robot=(cls='',finish)=>`<div class="bot ${cls}" aria-hidden="true">${grokBotSVG(finish||(cls==='small-bot'?'violet':cls==='tiny-bot'?'lime':'pearl'))}</div>`;
const face=(finish='pearl')=>`<div class="crew-face" data-bot-style="${finish}" aria-hidden="true">${grokBotSVG(finish)}</div>`;
const bots=[{id:'orbit',name:'Orbit',role:'Ideas & direction',color:'pearl',system:'You are Orbit, a curious creative planning assistant in Grok SI Labs. Help users shape app ideas and bot concepts into clear, practical specifications. Be concise and approachable. Never claim to perform actions or to have live market data.'},{id:'byte',name:'Byte',role:'Code & creation',color:'violet',system:'You are Byte, a pragmatic web developer in Grok SI Labs. Help build and debug apps using HTML, CSS, and JavaScript. Explain code clearly. Do not claim code is tested unless actual test results are provided.'},{id:'mint',name:'Mint',role:'Tokens & launches',color:'lime',system:'You are Mint, a token setup assistant in Grok SI Labs. Help with token names, descriptions, community planning and understanding pump.fun launches. Do not promise profits or fabricate market data. Wallet signatures and network fees are required; you cannot launch tokens yourself.'}];
function read(key,fallback){try{return JSON.parse(localStorage.getItem('gb:'+key))??fallback}catch{return fallback}}
const state={signedIn:false,sharedLaunches:[],launchTotal:0,launchNext:null,launchFeedReady:false,cloud:[],cloudReady:false,builds:read('builds',[]),saved:read('saved',[]),runs:read('runs',{}),launches:read('launches',[]),filter:'All',query:'',wallet:null,key:'',configured:false,activeBot:'orbit',chats:{orbit:[],byte:[],mint:[]},chatBusy:false,building:false,current:null,previewURL:null,source:false,prompt:'',desktop:null,prepared:null};
function persist(){try{localStorage.setItem('gb:builds',JSON.stringify(state.builds));localStorage.setItem('gb:saved',JSON.stringify(state.saved));localStorage.setItem('gb:runs',JSON.stringify(state.runs));localStorage.setItem('gb:launches',JSON.stringify(state.launches));}catch{toast('Browser storage is full. Export your creations to keep them.')}$('#my-count').textContent=allCreationsEntries(state.cloud,state.builds).length+state.launchTotal;}
function drawIcons(){createIcons({icons,attrs:{'aria-hidden':'true'}})}
let lastCreation=null,lastCloudCreation=null;let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function modal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();drawIcons()}
function closeModal(){$('#modal').close()}
function title(k,name,desc,extra=''){return `<div class="page-title"><div><div class="eyebrow">${k}</div><h1>${name}</h1><p>${desc}</p></div>${extra}</div>`}
function empty(h,p,cta='Start a creation',url='#/build'){return `<div class="empty">${icon('sprout')}<h3>${h}</h3><p>${p}</p><a class="btn primary" href="${url}">${cta}${icon('arrow-up-right')}</a></div>`}
function allBuilds(){const local=state.builds.filter(b=>!state.cloud.some(c=>c.id===b.id));return [...state.cloud,...local,...templates.map(t=>({...t,starter:true,created:0,html:templateHTML(t.id)}))]}
function getBuild(id){return allBuilds().find(b=>b.id===id)}
function art(b){const token=state.sharedLaunches.find(l=>l.mint===b.mint||l.project_id===b.id);let content='';if(token?.image_uri)return `<a class="card-art creation-token-art" href="#/creation/${esc(b.id)}" aria-label="Open ${esc(b.name)}"><img class="token-pfp-image" src="${esc(token.image_uri)}" alt="${esc(token.name)} token PFP" loading="lazy" referrerpolicy="no-referrer"><div class="token-pfp-fallback" hidden>${grokBotSVG('violet','creation-'+b.id)}</div></a>`;if(b.art==='orbit')content=robot('',b.id==='orbit'?'ice':finishForIdentity(b.id));else if(b.art==='lavender')content='<div class="pomodoro">25:00</div>';else if(b.art==='orange')content=`<div class="meme-box"><span class="match-grok">${grokBotSVG('copper')}</span><b>?</b><b>?</b><span class="match-grok">${grokBotSVG('rose')}</span></div>`;else if(b.art==='grid')content='<div class="mini-window"><div class="window-dots">● ● ●</div><div class="demo-title">YOUR NEXT IDEA, CALCULATED.</div><div class="mini-number">0.720 <span style="font-size:10px;letter-spacing:0">SOL</span></div><div class="bars">'+[25,45,36,66,49,85,72,100].map(n=>`<span style="--h:${n}%"></span>`).join('')+'</div></div>';else if(b.art==='dark')content='<div class="mini-window"><div class="window-dots">● ● ●</div><div class="demo-title">A LITTLE STRUCTURE. A LOT OF POSSIBILITY.</div><div class="kanban"><div><span></span><span></span><span></span></div><div><span></span><span></span></div><div><span></span></div></div></div>';else content='<div class="mini-window"><div class="window-dots">● ● ●</div><div class="mini-notes">little thoughts.<br>______________<br>01. what if we...</div></div>';return `<a class="card-art art-${b.art||'orbit'}" href="#/creation/${b.id}" aria-label="Open ${esc(b.name)}"><span class="art-badge">${esc(b.category||'APP')} / ${b.starter?'STARTER':b.cloud&&b.published?'COMMUNITY CREATION':'YOUR DRAFT'}</span>${content}</a>`}
function card(b){const token=state.sharedLaunches.find(l=>l.mint===b.mint||l.project_id===b.id);return `<article class="creation-card">${art(b)}<div class="card-content"><div class="card-title-row"><h3><a href="#/creation/${b.id}">${esc(b.name)}</a></h3><button class="${state.saved.includes(b.id)?'saved':''}" data-action="save" data-id="${b.id}" aria-label="${state.saved.includes(b.id)?'Unsave':'Save'} ${esc(b.name)}">${icon('bookmark')}</button></div><p>${esc(b.description)}</p><div class="card-meta"><span class="author"><span class="avatar">${b.starter?'g':'y'}</span>${b.starter?'@groksilabs':b.owned===false?'@maker':'@you'}</span><span>${b.starter?'Remixable starter':new Date(b.created).toLocaleDateString()}</span></div>${token?`<div class="creation-ca"><span>CA:</span><code>${esc(token.mint)}</code><button data-action="copy-token-ca" data-id="${esc(token.mint)}" aria-label="Copy ${esc(token.name)} contract address">${icon('copy')}</button></div>`:''}<div class="card-bottom"><span>${b.opens??state.runs[b.id]??0} ${b.cloud?'opens':'local opens'}</span><a href="#/creation/${b.id}">Explore ${icon('arrow-up-right')}</a></div></div></article>`}
function discover(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="status-dot"></span>EXPERIMENT. CREATE. LAUNCH.</div><h1>GROK<br><em>SI LABS</em></h1><p class="hero-subtitle">THE SUPER INTELLIGENT LABORATORY</p><p>A curious crew. A little controlled chaos.<br>Mix your ideas into something extraordinary.</p><div class="hero-actions"><a class="btn primary" href="#/build">Let’s build something ${icon('arrow-up-right')}</a><a class="btn ghost" href="#/guide">Inside the lab ${icon('arrow-right')}</a></div><div class="hero-foot"><span class="status-dot"></span> Make it. Play with it. Give it a token.</div></div><div class="lab-scene"><div class="lab-scene-halo" aria-hidden="true"></div><img src="/assets/grok-laboratory.webp" alt="Pearl, purple, and mint Grok bot scientists in white lab coats experimenting with flasks, beakers, green and purple ooze, and overflowing foam" width="1024" height="1024" fetchpriority="high"><span class="lab-scene-caption"><span class="status-dot"></span> GENIUS AT WORK. EXPECT BUBBLES.</span></div></section><form class="prompt-bar" id="quick-build"><span class="prompt-icon">${icon('sparkles')}</span><input name="idea" aria-label="Describe your idea" placeholder="A bot that turns my wild ideas into something real…" maxlength="2000" required><span class="enter">↵ ENTER</span><button class="btn primary" type="submit">Make it happen ${icon('arrow-up-right')}</button></form>${communityBox()}<div class="section-head"><div><h2>A little inspiration.</h2><p>Working starters and creations from across the laboratory. Pick one. Make it yours.</p></div><a class="text-link" href="#/mine">All creations ${icon('arrow-up-right')}</a></div><div class="discover-grid"><div><div class="filter-bar"><div class="tabs" role="group" aria-label="Creation categories">${['All','Bots','Tools','Games','Saved'].map(t=>`<button data-action="filter" data-filter="${t}" class="${state.filter===t?'selected':''}" aria-pressed="${state.filter===t}">${t}</button>`).join('')}</div><label class="search-wrap">${icon('search')}<input id="gallery-search" aria-label="Search creations" placeholder="Find your next idea" value="${esc(state.query)}"></label></div><div class="cards" id="gallery-cards">${filteredCards()}</div></div><aside class="discover-rail"><section class="rail-panel"><h2 class="rail-label">YOUR BOT CREW ${icon('orbit')}</h2>${bots.map(b=>`<a class="crew-row" href="#/room/${b.id}">${face(b.color)}<span><strong>${b.name}</strong><small>${b.role}</small></span>${icon('arrow-up-right')}</a>`).join('')}<div class="crew-footer">${icon('sparkles')} Three roles. One shared curiosity.</div></section><section class="rail-panel launch-panel"><div class="big-pill"></div><span class="eyebrow">FROM IDEA TO ONCHAIN</span><h3>Your creation.<br>Its own little economy.</h3><p>Give your project a token on pump.fun. Keep your keys. Sign your own launch.</p><a class="btn primary small" href="#/launch">Enter the launchpad ${icon('arrow-up-right')}</a></section><div class="rail-notes"><h3>Made for the makers.</h3><p>Save your creations to the cloud.<br>Keep a local copy whenever you like.<br><a href="#/guide">A few things to know ↗</a></p></div></aside></div>`}
function filteredCards(){const q=state.query.toLowerCase();const builds=allBuilds().filter(b=>(state.filter==='All'||state.filter==='Saved'&&state.saved.includes(b.id)||b.category===state.filter)&&(!q||(b.name+' '+b.description).toLowerCase().includes(q)));return builds.length?builds.map(card).join(''):'<p class="notice">No creations match yet. Try another category or search.</p>'}
function buildPage(){return title('THE BUILD STUDIO','A spark. A little teamwork.','Tell the crew what’s on your mind. Watch the plan, build, and review take shape.')+`<div class="workspace-grid"><section class="panel"><h2>What are we making?</h2><form id="build-form"><label class="field">Give it a name<input name="name" placeholder="My next big thing" maxlength="60" required value="${esc(state.current?.name||'')}"></label><label class="field">Project idea / description<textarea name="prompt" placeholder="A playful tool that…" maxlength="5000" required>${esc(state.prompt)}</textarea></label><label class="field">How should we start?<select name="mode"><option value="starter" selected>Free starter builder</option><option value="grok">Grok AI (API key required)</option></select></label><label class="field" id="starter-field">Choose a starting point<select name="starter">${templates.map(t=>`<option value="${t.id}">${t.name}</option>`).join('')}</select></label><label class="check-label"><input type="checkbox" name="published" ${state.current?.published===false?'':'checked'}><span>List this creation publicly in All creations and on the homepage after it saves to the cloud. <small>Sign in to save and share. Uncheck to keep a private draft.</small></span></label><button class="btn primary full" type="submit" ${state.building?'disabled':''}>${icon('sparkles')}${state.building?'Crew is creating…':'Bring it to life'}${icon('arrow-up-right')}</button></form><div class="preset-chips"><button data-action="preset" data-id="focus">A focus timer</button><button data-action="preset" data-id="memory">A tiny game</button><button data-action="preset" data-id="board">A launch board</button></div><div class="step-list">${[['Orbit plans','The idea becomes a practical blueprint.'],['Byte builds','Your app becomes a single working page.'],['Mint reviews','A second pass checks and improves the code.']].map((s,i)=>`<div class="step" id="step-${i}"><span class="step-index">${i+1}</span><div><b>${s[0]}</b><span>${s[1]}</span></div></div>`).join('')}</div><p class="tip">Free starter mode requires no API key. It builds from your selected template. Optional Grok AI uses your own API credits.</p></section><section class="panel preview-panel"><div class="panel-bar"><span class="window-dots">● ● ●</span><span>YOUR LIVE PREVIEW</span><div class="width-controls"><button data-action="viewport" data-width="100%" aria-label="Desktop preview">${icon('monitor')}</button><button data-action="viewport" data-width="375px" aria-label="Mobile preview">${icon('smartphone')}</button></div><button data-action="source" class="icon-btn" aria-label="Toggle source code">${icon('code-2')}</button></div><div id="preview-space" class="preview-viewport"><div class="preview-empty">${face()}<h3>The canvas is yours.</h3><p>Give the crew an idea, or remix a starter. Your working preview will appear here.</p></div></div><div class="build-log" id="build-log" aria-live="polite">Ready when you are. Let’s make something worth opening.</div></section></div><div id="build-actions" class="detail-actions hidden" style="margin-top:18px"><button class="btn" data-action="export-current">${icon('download')}Export HTML</button><button class="btn" data-action="launch-current">${icon('rocket')}Give it a token</button><a class="btn" href="#/mine">${icon('layers-3')}All creations</a></div>`}
function roomPage(id){if(bots.some(b=>b.id===id))state.activeBot=id;const b=bots.find(b=>b.id===state.activeBot);return title('THE BOT ROOM','Good ideas start with a conversation.','Pick a perspective. Ask a question. Follow the interesting bits.')+`<div class="room-grid"><aside><div class="bot-picker">${bots.map(x=>`<button data-action="pick-bot" data-id="${x.id}" class="bot-choice ${x.id===b.id?'selected':''}">${face(x.color)}<span><b>${x.name}</b><small>${x.role}</small></span></button>`).join('')}</div><div class="notice">Live chat is powered by Grok. Add your xAI key in Settings. Conversations stay in memory for this visit.</div><button class="btn small" data-action="clear-chat">${icon('trash-2')}Clear conversation</button></aside><section class="panel chat-panel"><div class="chat-top">${face(b.color)}<span>${b.name}<small>${b.role} · Grok-powered conversation</small></span></div><div class="chat-history" id="chat-history">${chatMessages()}</div><form class="chat-compose" id="chat-form"><textarea name="message" aria-label="Message ${b.name}" placeholder="A question, a spark, a wild what-if…" maxlength="6000" required ${state.chatBusy?'disabled':''}></textarea><button class="btn primary" type="submit" ${state.chatBusy?'disabled':''} aria-label="Send message">${icon('arrow-up')}</button></form></section></div>`}
function chatMessages(){const b=bots.find(x=>x.id===state.activeBot);return state.chats[b.id].length?state.chats[b.id].map(m=>`<div class="message ${m.role}"><span class="msg-author">${m.role==='user'?'YOU':b.name.toUpperCase()}</span>${esc(m.content)}</div>`).join(''):`<div class="message assistant"><span class="msg-author">${b.name.toUpperCase()}</span>${b.id==='orbit'?'What have you been curious about lately? Bring me the messy version of an idea. We’ll give it some shape.':b.id==='byte'?'Let’s make something work. Tell me what you’re building, or paste the code you want to improve.':'Have a creation that needs a token? Let’s work through the name, identity, and launch details together.'}</div>`}
function launchPage(){const drafts=allBuilds().filter(b=>!b.starter&&b.owned!==false);return title('THE TOKEN LAUNCHPAD','Give your idea a life onchain.','Create a SOL-paired token directly on pump.fun. Your wallet stays in charge. Pending launches can be checked in All creations.',`<a class="btn small" href="https://pump.fun/create" target="_blank" rel="noopener">Open pump.fun ${icon('arrow-up-right')}</a>`)+`<div class="launch-layout"><section class="panel"><h2>Make it yours.</h2><form id="launch-form"><label class="field">Link a creation <span class="muted">(optional)</span><select name="buildId"><option value="">A standalone token</option>${drafts.map(b=>`<option value="${b.id}" ${state.current?.id===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><div class="two-fields"><label class="field">Token name<input name="name" id="token-name" placeholder="Orbit Companion" maxlength="32" required value="${esc(state.current?.name?.slice(0,32)||'')}"></label><label class="field">Ticker<input name="symbol" id="token-symbol" placeholder="ORBIT" maxlength="13" pattern="[A-Za-z0-9]{1,13}" required></label></div><label class="field">What’s the story?<textarea name="description" id="token-description" placeholder="A little bot. A shared idea. A community built around curiosity." maxlength="2000" required>${esc(state.current?.description||'')}</textarea></label><label class="field">Token image<input type="file" name="image" id="token-image" accept="image/png,image/jpeg,image/webp,image/gif"><small>PNG, JPG, GIF or WebP · Up to 5 MB. Uploaded to pump.fun when you prepare the launch.</small></label><label class="field">Existing metadata JSON URL <span class="muted">(optional)</span><input name="uri" type="url" placeholder="https://…/metadata.json"><small>Provide a public HTTPS metadata JSON URL to skip image upload. Metadata is permanent; check it carefully.</small></label><div class="two-fields"><label class="field">Website<input name="website" type="url" placeholder="https://your-project.com"></label><label class="field">X profile<input name="twitter" type="url" placeholder="https://x.com/your-project"></label></div><label class="field">Telegram<input name="telegram" type="url" placeholder="https://t.me/your-community"></label><div class="panel dev-buy-panel"><h3>Optional dev buy</h3><label class="check-label"><input type="checkbox" name="devBuy" id="dev-buy-enabled"><span>Buy tokens into my connected wallet as part of this launch.</span></label><label class="field">Maximum buy budget (SOL)<input name="devBuySol" id="dev-buy-sol" type="text" inputmode="decimal" placeholder="0.1" disabled><small>Off by default. When enabled, creation and buy happen in one transaction. The budget includes pump.fun trading fees; account rent and network fees are additional. Minimum tokens use 1% slippage.</small></label></div><label class="field">Optional network priority fee (SOL)<input name="prioritySol" type="text" inputmode="decimal" value="0" placeholder="0.00005"><small>0 adds no priority fee. A small fee such as 0.00005 SOL can help during congestion. Maximum 0.01 SOL; included in your review.</small></label><label class="check-label"><input type="checkbox" name="holderReward"><span>Use holder rewards instead of creator fees. This choice is permanent. <a href="https://github.com/pump-fun/pump-public-docs/blob/main/docs/HOLDER_REWARDS_README.md" target="_blank" rel="noopener">Read how it works ↗</a></span></label><label class="check-label"><input type="checkbox" name="ack" required><span>I have reviewed the token details and understand this creates a real token on Solana mainnet and uses SOL for account rent and network fees.</span></label><button class="btn primary full" type="submit">${icon('scan-line')}Prepare & review launch ${icon('arrow-right')}</button><div id="launch-error" role="alert"></div></form><p class="tip">The studio builds a pump.fun create_v2 transaction with the official SDK. You review a simulation before signing. An optional dev buy is included only when enabled. No studio service fee is added.</p></section><aside><div class="sticky"><div class="token-preview"><div class="eyebrow" style="justify-content:center">A FIRST LOOK</div><div class="token-art" id="token-art">${robot('','lime')}</div><h3 id="preview-token-name">${esc(state.current?.name||'Your next big idea')}</h3><span class="ticker" id="preview-token-symbol">$YOURTICKER</span><p id="preview-token-desc">A little identity goes a long way.</p><div class="info-row"><span>Network</span><span>Solana mainnet</span></div><div class="info-row"><span>Launch venue</span><span>pump.fun</span></div><div class="info-row"><span>Pair</span><span>SOL</span></div><div class="info-row"><span>Dev buy</span><span id="preview-dev-buy">Off</span></div><div class="info-row"><span>Signing</span><span>Your wallet</span></div></div><div class="notice">A token launch is permanent. Network costs are paid in SOL. You can cancel at any time before signing.</div></div></aside></div>`}
function communityBox(){const creations=publicCreationsEntries(state.cloud);return `<section class="community-box" aria-label="All creations from the community"><div class="section-head"><div><div class="eyebrow">MADE IN THE LAB · BY EVERYONE</div><h2>All creations</h2><p>Fresh ideas from the whole community, together in one place.</p></div><a class="btn small" href="#/mine">View all ${icon('arrow-up-right')}</a></div>${creations.length||state.sharedLaunches.length?`${state.sharedLaunches.length?`<div class="launched-token-grid">${state.sharedLaunches.slice(0,2).map(launchCard).join('')}</div>`:''}${creations.length?`<div class="community-cards" style="margin-top:18px">${creations.slice(0,3).map(card).join('')}</div>`:''}<p class="community-count">${creations.length} shared creations · ${state.launchTotal} launched tokens.</p>`:`<div class="community-empty">${face('violet')}<div><h3>The next discovery could be yours.</h3><p>New shared builds appear here after saving to the cloud. Sign in and bring the first idea to life.</p></div><a class="btn primary" href="#/build">Create something ${icon('plus')}</a></div>`}</section>`}
function publicLaunchGallery(){return `<section class="launch-gallery" aria-label="Tokens launched from this site"><div class="section-head"><div><div class="eyebrow">CREATED HERE · LIVE ONCHAIN</div><h2>Launched from GROK SI LABS</h2><p>Tokens launched by people using this studio, with their PFP and contract address.</p></div><a class="btn primary small" href="#/launch">Launch a coin ${icon('rocket')}</a></div>${state.sharedLaunches.length?`<div class="launched-token-grid">${state.sharedLaunches.map(launchCard).join('')}</div>${state.launchNext!==null?'<button class="btn" data-action="load-launches">Load more launches</button>':''}`:state.launchFeedReady?'<div class="notice">Confirmed launches will appear here with their PFP and CA.</div>':'<div class="notice" role="status">Loading confirmed launches…</div>'}</section>`}
function minePage(){const creations=allCreationsEntries(state.cloud,state.builds);return title('THE COMMUNITY LABORATORY','All creations','Explore creations from everyone in the lab. Your own saved drafts appear here too.',`<a class="btn primary small" href="#/build">${icon('plus')}New creation</a>`)+publicLaunchGallery()+'<h2 class="divider-label">CREATIONS BY THE COMMUNITY</h2>'+(creations.length?`<div class="saved-strip">${publicCreationsEntries(state.cloud).length} shared creations · ${creations.length} available to you · ${state.cloudReady?'Cloud connected':'Loading community creations…'}</div><div class="cards all-creations-grid">${creations.map(card).join('')}</div>`:empty('The laboratory is ready for its first discovery.','Creations shared by anyone will appear here. Build an idea and save it to the cloud.'))+(state.launches.length?`<h2 class="divider-label">YOUR TOKEN LAUNCHES</h2><div class="table-wrap"><table><thead><tr><th>TOKEN</th><th>STATUS</th><th>ONCHAIN</th></tr></thead><tbody>${state.launches.map(l=>`<tr><td>${esc(l.name)}<small>$${esc(l.symbol)}</small></td><td>${esc(l.status)}${(l.status!=='confirmed'||l.receipt&&!l.gallerySaved)?`<br><button class="btn small" data-action="check-launch" data-id="${esc(l.mint)}">Check status</button>`:''}</td><td><a href="https://pump.fun/coin/${esc(l.mint)}" target="_blank" rel="noopener">pump.fun ↗</a>${l.signature?` · <a href="https://solscan.io/tx/${esc(l.signature)}" target="_blank" rel="noopener">Transaction ↗</a>`:''}</td></tr>`).join('')}</tbody></table></div>`:'')}
function leaderboardPage(){const builds=allBuilds().filter(b=>(b.opens??state.runs[b.id]??0)>0).sort((a,b)=>(b.opens??state.runs[b.id]??0)-(a.opens??state.runs[a.id]??0));return title('THE CURIOSITY CHART','Your most explored creations.','Real recorded opens for shared projects, plus your local starter activity.')+(builds.length?`<div class="table-wrap"><table><thead><tr><th>RANK</th><th>CREATION</th><th>CATEGORY</th><th>OPENS</th><th></th></tr></thead><tbody>${builds.map((b,i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td><b>${esc(b.name)}</b><small>${b.starter?'Grokbots starter':'Your creation'}</small></td><td>${b.category}</td><td>${b.opens??state.runs[b.id]??0}</td><td><a href="#/creation/${b.id}">Explore ↗</a></td></tr>`).join('')}</tbody></table></div>`:empty('Curiosity makes the leaderboard.','Open a few creations and your most explored projects will appear here.','Explore creations','#/discover'))}
function guidePage(){return title('HOW IT WORKS','A small idea. A complete journey.','Build something useful, make it your own, and decide where it goes next.')+`<div class="guide-grid">${[['01 / SPARK','Give the crew a direction.','Describe a useful tool, a tiny game, or a bot with personality. Use Grok for a fresh build or choose a working starter without an API key.'],['02 / CREATE','Watch the work take shape.','Orbit drafts a plan, Byte generates the app, and Mint reviews the code. Those are three Grok requests with different roles. Each stage shows its result.'],['03 / EXPLORE','Play. Remix. Keep a copy.','Try the live sandbox, inspect the code, switch to a phone preview, or export an HTML file. Creations can be saved to the cloud and shared with visitors who have access to this site.'],['04 / LAUNCH','Put a token behind your idea.','Choose the name, ticker, image, and reward mode. Prepare the official pump.fun transaction, inspect the simulation, then approve it in Phantom or Solflare.'],['05 / CONNECT','Keep your companion close.','The optional desktop bridge pairs this site with your installed Grok Bot app. It reports whether the app is running and opens it on request. Chat and generation use the xAI API separately.'],['06 / YOUR KEYS','A workspace you can understand.','The site never asks for a wallet seed phrase or private key. API keys entered in Settings stay in page memory and are sent through the server to xAI only. Reloading clears them.']].map(([n,h,p])=>`<section class="panel"><div class="guide-number">${n}</div><h2>${h}</h2><p>${p}</p></section>`).join('')}</div>`}
function detailPage(id){const b=getBuild(id);if(!b)return empty('This creation isn’t on this device.','Import its exported project file or return to the gallery.','Explore creations','#/discover');state.current=b;if(lastCreation!==id){state.runs[id]=(state.runs[id]||0)+1;lastCreation=id;}persist();if(b.cloud&&lastCloudCreation!==id){lastCloudCreation=id;b.opens=(b.opens||0)+1;fetch('/api/projects/'+encodeURIComponent(id)+'/open',{method:'POST'}).catch(()=>{});}return title(b.starter?'THE STARTER LAB':'YOUR CREATION',esc(b.name),esc(b.description),`<button class="btn small" data-action="share" data-id="${b.id}">${icon('share-2')}Share</button>`)+`<div class="detail-grid"><section class="panel preview-panel"><div class="panel-bar"><span class="window-dots">● ● ●</span><span>PLAY WITH THE IDEA</span><div class="width-controls"><button data-action="viewport" data-width="100%" aria-label="Desktop preview">${icon('monitor')}</button><button data-action="viewport" data-width="375px" aria-label="Mobile preview">${icon('smartphone')}</button></div><button class="icon-btn" data-action="source" aria-label="Toggle source code">${icon('code-2')}</button></div><div id="preview-space" class="preview-viewport"></div></section><aside><section class="panel"><span class="tag">${esc(b.category)}</span><span class="tag">${b.starter?'Starter':b.cloud&&b.published?'Shared creation':b.cloud?'Cloud draft':'Local draft'}</span><h2 style="margin-top:20px">Follow the spark.</h2><p>${b.starter?'A working starter built for remixing. Customize it in the studio, or take the source and go your own way.':'A working creation with a local backup. Save it to the cloud or export the source to keep your own copy.'}</p><div class="detail-actions"><button class="btn primary full" data-action="remix" data-id="${b.id}">${icon('git-fork')}Remix in studio</button><button class="btn full" data-action="export-current">${icon('download')}Export HTML</button>${!b.starter&&b.owned!==false?`<button class="btn full" data-action="publish-project" data-id="${b.id}">${icon(b.cloud&&b.published?'eye-off':'globe')}${b.cloud&&b.published?'Make this creation private':'Share to All creations'}</button>`:''}<button class="btn full" data-action="export-project">${icon('file-json')}Export project</button><button class="btn full" data-action="launch-current">${icon('rocket')}Give it a token</button></div><div class="divider-label">LOCAL ACTIVITY</div><div class="info-row"><span>Opens on this device</span><span>${state.runs[b.id]}</span></div><div class="info-row"><span>Token</span><span>${b.mint?`<a href="https://pump.fun/coin/${b.mint}" target="_blank" rel="noopener">View on pump.fun ↗</a>`:'Not launched'}</span></div>${b.starter||b.owned===false?'':`<button class="btn full danger" style="margin-top:20px" data-action="delete" data-id="${b.id}">${icon('trash-2')}Remove creation</button>`}</section><p class="tip">Previews run in an isolated sandbox with network requests disabled. Export the app to deploy it elsewhere.</p></aside></div>`}
function route(){if(state.building){if(!location.hash.startsWith('#/build')){toast('The crew is still working. Stay in the studio until the build finishes.');location.hash='/build';}return;}const [page='discover',id]=location.hash.replace(/^#\/?/,'').split('/');const names={discover:'Discover',build:'Build studio',room:'Bot room',launch:'Token launchpad',mine:'All creations',leaderboard:'Leaderboard',guide:'How it works',creation:'Creation'};if(page!=='creation'){lastCreation=null;lastCloudCreation=null;}$('#page-name').textContent=names[page]||'Discover';$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));document.body.classList.remove('menu-open');state.source=false;$('#main').innerHTML=page==='build'?buildPage():page==='room'?roomPage(id):page==='launch'?launchPage():page==='mine'?minePage():page==='leaderboard'?leaderboardPage():page==='guide'?guidePage():page==='creation'?detailPage(id):discover();drawIcons();if(page==='creation'&&state.current)showPreview(state.current.html);if(page==='build'&&state.current?.html){showPreview(state.current.html);$('#build-actions').classList.remove('hidden')}window.scrollTo(0,0);}
function showPreview(html){const space=$('#preview-space');if(!space)return;if(state.previewURL)URL.revokeObjectURL(state.previewURL);if(state.source){const pre=document.createElement('pre');pre.className='source-view';pre.textContent=html;space.replaceChildren(pre);return}const frame=document.createElement('iframe');frame.className='preview-frame';frame.title='Creation preview';frame.setAttribute('sandbox','allow-scripts allow-downloads');frame.setAttribute('referrerpolicy','no-referrer');state.previewURL=URL.createObjectURL(new Blob([sandboxHTML(html)],{type:'text/html'}));frame.srcdoc=sandboxHTML(html);space.replaceChildren(frame);}
async function grok(messages,max_tokens=3000){const res=await fetch('/api/grok',{method:'POST',headers:{'Content-Type':'application/json',...(state.key?{'X-Grok-Key':state.key}:{})},body:JSON.stringify({messages,max_tokens})});const d=await res.json();if(!res.ok)throw Error(d.error||'Grok request failed');return d.text;}
const log=(message)=>{const el=$('#build-log');if(el){el.textContent+='\n'+message;el.scrollTop=el.scrollHeight}};
function step(n,status){const el=$('#step-'+n);if(el)el.className='step '+status;}
async function startBuild(form){if(state.building)return;const d=Object.fromEntries(new FormData(form));d.published=form.elements.published.checked;state.prompt=d.prompt;if(d.mode==='grok'&&!state.key&&!state.configured){settings();toast('Add your xAI key, or choose “Remix a working starter”.');return}state.building=true;form.querySelector('button[type=submit]').disabled=true;let html='';try{if(d.mode==='starter'){const base=templates.find(x=>x.id===d.starter);step(0,'done');log('Orbit: Using the '+base.name+' starter.');html=templateHTML(base.id);step(1,'done');log('Byte: Starter source loaded.');step(2,'done');log('Mint: Ready to preview. No AI requests were made.');}else{step(0,'running');log('Orbit: Turning your idea into a practical plan…');const plan=await grok([{role:'system',content:bots[0].system+' Return a concise implementation plan for a self-contained browser app, including its key interactions and visual direction. No backend or external dependencies.'},{role:'user',content:d.prompt}],1200);step(0,'done');log('Orbit: '+plan);step(1,'running');log('Byte: Building the app…');const generated=await grok([{role:'system',content:'You are Byte, a senior frontend engineer. Return ONLY a complete standalone HTML document with inline CSS and JavaScript. Build a polished responsive working app for the user idea and plan. For any Grok bot illustration, use a smooth circular sphere with two dark diagonal rounded capsule eyes near its upper-right face, matching the studio bot. Give each bot a different surface color or finish while keeping the sphere and eye geometry identical. Do not give Grok bots antennas, limbs, bodies, ears, or a rectangular head. No external dependencies, network, forms to external services, wallet access, eval, popups, parent access or localStorage. Use in-memory state. Accessible semantic controls. Implement all primary interactions, no placeholders.'},{role:'user',content:'App name: '+d.name+'\nIdea: '+d.prompt+'\nPlan: '+plan}],11000);html=generated.replace(/^```(?:html)?\s*/i,'').replace(/\s*```$/,'');if(!/<html|<!doctype/i.test(html))throw Error('The generated response was not an HTML app. Please try a more specific idea.');step(1,'done');showPreview(html);step(2,'running');log('Mint: Reviewing the app for broken interactions…');try{const reviewed=await grok([{role:'system',content:'You are a careful frontend code reviewer. Review this self-contained HTML app. Fix concrete JavaScript, accessibility or responsive issues. Return ONLY the full corrected HTML document with inline CSS/JS, no markdown. Keep in-memory state, no network or external resources.'},{role:'user',content:html}],12000);const cleaned=reviewed.replace(/^```(?:html)?\s*/i,'').replace(/\s*```$/,'');if(/<html|<!doctype/i.test(cleaned))html=cleaned;log('Mint: Code review completed. Try the interactions in the preview.');}catch(e){log('Mint: Review was unavailable: '+e.message+'. The generated draft is preserved.')}step(2,'done');}const b={id:crypto.randomUUID(),published:d.published,name:d.name.trim(),description:d.prompt.trim().slice(0,170),prompt:d.prompt,html,category:'Tools',art:d.mode==='starter'?templates.find(t=>t.id===d.starter).art:'orbit',created:Date.now()};state.builds.unshift(b);state.current=b;persist();await syncProject(b);showPreview(html);$('#build-actions')?.classList.remove('hidden');log(b.cloud?(b.published?'Saved and listed publicly in All creations and on the homepage.':'Saved as your private draft in All creations.'):'Saved locally in All creations. Sign in and use Share to list it for everyone.');toast('Your creation is ready to explore.')}catch(e){log('Build stopped: '+e.message);toast(e.message)}finally{state.building=false;form.querySelector('button[type=submit]').disabled=false;}}
async function sendChat(form){if(state.chatBusy)return;if(!state.key&&!state.configured){settings();toast('Add an xAI API key to start a live conversation.');return}const content=new FormData(form).get('message').trim();if(!content)return;const id=state.activeBot;state.chats[id].push({role:'user',content});state.chatBusy=true;form.reset();$('#chat-history').innerHTML=chatMessages()+'<div class="message assistant loading-text" id="thinking">Thinking about that…</div>';form.querySelector('button').disabled=true;form.querySelector('textarea').disabled=true;try{const reply=await grok([{role:'system',content:bots.find(b=>b.id===id).system},...state.chats[id].slice(-24)]);state.chats[id].push({role:'assistant',content:reply})}catch(e){state.chats[id].push({role:'assistant',content:'Could not get a response: '+e.message})}finally{state.chatBusy=false;if($('#chat-history')){$('#chat-history').innerHTML=chatMessages();$('#chat-history').scrollTop=$('#chat-history').scrollHeight;$('#chat-form button').disabled=false;$('#chat-form textarea').disabled=false;}}}
function settings(){modal(`<div class="modal-eyebrow">MAKE YOURSELF AT HOME</div><h2>Settings & connections.</h2><div class="settings-section"><h3>Grok intelligence</h3><p>Add an xAI API key to power bot conversations and app generation. The key stays in page memory until you reload and is forwarded only to xAI through this site’s server. API usage is billed by xAI.</p><form id="key-form"><label class="field">xAI API key<input type="password" name="key" placeholder="xai-…" autocomplete="off" required><small>${state.configured?'A server API key is configured.':state.key?'A session key is active.':'No API key connected yet.'} <a href="https://console.x.ai" target="_blank" rel="noopener">Get a key ↗</a></small></label><button class="btn primary small" type="submit">Use for this visit</button>${state.key?'<button type="button" class="btn small" data-action="clear-key">Forget key</button>':''}</form></div><div class="settings-section"><h3>Desktop companion</h3><p>Pair the local bridge to check and open your installed Grok Bot app. The bridge does not read desktop conversations or automate the app.</p><button class="btn small" data-action="desktop">${icon('monitor')}Pair desktop companion</button></div><div class="settings-section"><h3>Keep your work</h3><p>Creations sync to cloud storage when you save. Bookmarks and starter activity stay on this browser. Public creations appear in All creations and on the homepage. Private drafts stay visible to their owner.</p><button class="btn small" data-action="import">${icon('upload')}Import project JSON</button><input id="import-file" type="file" accept="application/json,.json" hidden></div>`)}
function walletModal(){if(state.wallet){const addr=state.wallet.publicKey.toString();modal(`<div class="modal-eyebrow">YOUR SOLANA WALLET</div><h2>You hold the keys.</h2><p class="inline-code">${esc(addr)}</p><div class="notice" id="wallet-balance">Loading your SOL balance…</div><div class="modal-actions"><button class="btn" data-action="copy-wallet">${icon('copy')}Copy address</button><a class="btn" href="https://solscan.io/account/${addr}" target="_blank" rel="noopener">Solscan ↗</a><button class="btn danger" data-action="disconnect">Disconnect</button></div>`);import('/launch.js').then(m=>m.rpc('getBalance',[addr,{commitment:'confirmed'}])).then(r=>{if($('#wallet-balance'))$('#wallet-balance').textContent=(r.value/1e9).toFixed(5)+' SOL · Mainnet'}).catch(e=>{if($('#wallet-balance'))$('#wallet-balance').textContent='Balance unavailable: '+e.message});return}modal(`<div class="modal-eyebrow">CONNECT TO CREATE ONCHAIN</div><h2>Your wallet. Your launch.</h2><p>Choose your installed Solana wallet. Connecting shares your public address; each token launch asks for a separate signature.</p><button class="wallet-option" data-action="connect-wallet" data-provider="phantom">${icon('ghost')}Phantom<span>${window.phantom?.solana||window.solana?.isPhantom?'Connect ↗':'Install ↗'}</span></button><button class="wallet-option" data-action="connect-wallet" data-provider="solflare">${icon('sun')}Solflare<span>${window.solflare?'Connect ↗':'Install ↗'}</span></button><p>Wallet extensions work in a supported browser. If you are viewing this in an embedded browser, open the site in Chrome or another wallet-enabled browser.</p>`)}
async function connectWallet(name){const provider=name==='phantom'?(window.phantom?.solana||(window.solana?.isPhantom?window.solana:null)):window.solflare;if(!provider){window.open(name==='phantom'?'https://phantom.com/download':'https://solflare.com/download','_blank','noopener');return}try{await provider.connect();if(!provider.publicKey)throw Error('Wallet did not provide an address');state.wallet=provider;provider.on?.('disconnect',walletReset);provider.on?.('accountChanged',()=>{state.prepared=null;if(provider.publicKey)updateWallet();else walletReset()});updateWallet();closeModal();toast('Wallet connected. Ready when you are.')}catch(e){toast('Wallet connection cancelled or unavailable.')}}
function updateWallet(){const address=state.wallet?.publicKey?.toString();$('#wallet-label').textContent=address?address.slice(0,4)+'…'+address.slice(-4):'Connect wallet';$('.wallet-btn .status-dot').classList.toggle('muted',!address)}function walletReset(){state.wallet=null;state.prepared=null;updateWallet()}
async function prepareToken(form){const button=form.querySelector('button[type=submit]');const error=$('#launch-error');error.innerHTML='';let d=Object.fromEntries(new FormData(form));d.holderReward=form.elements.holderReward.checked;d.devBuy=form.elements.devBuy.checked;try{solToLamports(d.devBuy?d.devBuySol:'0','Dev buy');solToLamports(d.prioritySol||'0','Priority fee');d=validateToken(d);if(!state.wallet){walletModal();return}if(!d.uri&&!form.elements.image.files[0])throw Error('Add a token image or an existing metadata JSON URL.');if(form.elements.image.files[0]?.size>5000000)throw Error('Image must be below 5 MB.');button.disabled=true;button.textContent='Preparing metadata & simulation…';if(!d.uri){const data=new FormData();data.set('file',form.elements.image.files[0]);for(const k of ['name','symbol','description','website','twitter','telegram'])data.set(k,d[k]||'');const response=await fetch('/api/metadata',{method:'POST',body:data});const metadata=await response.json();if(!response.ok||!metadata.metadataUri)throw Error(metadata.error||'Metadata upload did not return a URL.');d.uri=metadata.metadataUri;}d=validateToken(d);const m=await import('/launch.js');const prepared=await m.prepareLaunch(d,state.wallet,message=>{button.textContent=message;});button.textContent='Saving the launch record…';const registration=await fetch('/api/launches/prepare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mint:prepared.mint,wallet:prepared.user,name:d.name,symbol:d.symbol,uri:d.uri,projectId:d.buildId||null})});const receipt=await registration.json();if(!registration.ok||!receipt.receipt)throw Error(receipt.error||'The public launch record could not be prepared. Try again.');prepared.galleryReceipt=receipt.receipt;state.prepared=prepared;modal(`<div class="modal-eyebrow">ONE LAST LOOK</div><h2>Ready for your wallet.</h2><p>The creation and any enabled dev buy passed simulation. Review the identity and network below before asking your wallet to sign.</p><div class="launch-review"><div class="info-row"><span>Token</span><span>${esc(d.name)} · $${esc(d.symbol)}</span></div><div class="info-row"><span>Network</span><span>Solana mainnet</span></div><div class="info-row"><span>Launch program</span><span>pump.fun · create_v2</span></div><div class="info-row"><span>Network fee (incl. priority)</span><span>~${(prepared.fee/1e9).toFixed(6)} SOL</span></div><div class="info-row"><span>Account rent</span><span>Additional SOL · wallet displays total</span></div><div class="info-row"><span>Reward mode</span><span>${d.holderReward?'Holder rewards':'Creator fees'}</span></div><div class="info-row"><span>Dev buy maximum</span><span>${prepared.devBuyLamports==='0'?'Off':esc(d.devBuySol)+' SOL'}</span></div>${prepared.minimumTokens?`<div class="info-row"><span>Minimum tokens (1% slippage)</span><span>${esc(formatTokenUnits(prepared.minimumTokens))}</span></div>`:''}<div class="info-row"><span>Priority fee</span><span>${(prepared.priorityLamports/1e9).toFixed(9)} SOL</span></div></div><p class="inline-code">Mint: ${prepared.mint}</p><p><a href="${esc(d.uri)}" target="_blank" rel="noopener">Inspect permanent metadata ↗</a></p><div class="notice">Creating this token is permanent. Check the full transaction and SOL costs in your wallet. Confirmed launches are listed publicly in All creations with the token PFP and CA. Cancel there if anything is unexpected.</div><div id="sign-status" class="log-message" aria-live="polite"></div><div class="modal-actions"><button class="btn primary" data-action="sign-launch">${icon('wallet')}Review & sign in wallet</button><button class="btn" data-action="close-modal">Keep editing</button></div>`)}catch(e){error.innerHTML='<div class="notice error">'+esc(e.message)+'</div>'}finally{button.disabled=false;button.innerHTML=icon('scan-line')+'Prepare & review launch '+icon('arrow-right');drawIcons()}}
function formatTokenUnits(raw){const n=BigInt(raw);return (n/1000000n).toLocaleString()+'.'+(n%1000000n).toString().padStart(6,'0');}
function saveLaunch(prepared,result){const old=state.launches.find(l=>l.mint===prepared.mint);const record={receipt:prepared.galleryReceipt,uri:prepared.data.uri,projectId:prepared.data.buildId||null,name:prepared.data.name,symbol:prepared.data.symbol,created:old?.created||Date.now(),devBuySol:prepared.data.devBuy?prepared.data.devBuySol:'0',...old,...result};if(old)Object.assign(old,record);else state.launches.unshift(record);persist();if(record.status==='confirmed'&&record.receipt)void syncLaunchRecord(old||record);}
async function checkSavedLaunch(button){const record=state.launches.find(l=>l.mint===button.dataset.id);if(!record)return;button.disabled=true;try{const m=await import('/launch.js');const result=await m.checkLaunch(record,message=>{button.textContent=message;});Object.assign(record,result);persist();if(result.status==='confirmed')await syncLaunchRecord(record);toast(result.message||(result.status==='confirmed'?'Confirmed on Solana.':'Still pending. Check Phantom activity before launching again.'));route();}catch(e){toast(e.message);button.disabled=false;button.textContent='Check status';}}
async function submitLaunch(button){
 if(!state.prepared||!state.wallet)return;button.disabled=true;const prepared=state.prepared;
 try{
  const m=await import('/launch.js');
  const result=await m.signAndSend(prepared,state.wallet,status=>{if($('#sign-status'))$('#sign-status').textContent=status},result=>saveLaunch(prepared,result));
  saveLaunch(prepared,{...result,status:'confirmed'});const b=state.builds.find(x=>x.id===prepared.data.buildId);if(b){b.mint=result.mint;syncProject(b).catch(()=>toast('Token confirmed. Link your creation again when cloud storage is available.'));}state.prepared=null;
  modal(`<div class="modal-eyebrow">CONFIRMED ON SOLANA</div><h2>Your idea is onchain.</h2><p>${esc(prepared.data.name)} ($${esc(prepared.data.symbol)}) has been created on the pump.fun program.${prepared.devBuyLamports!=='0'?' Your dev buy was included in the same transaction.':''}</p><p class="inline-code">${result.mint}</p><div class="modal-actions"><a class="btn primary" href="https://pump.fun/coin/${result.mint}" target="_blank" rel="noopener">View on pump.fun ↗</a><a class="btn" href="https://solscan.io/tx/${result.signature}" target="_blank" rel="noopener">View transaction ↗</a></div><p>The pump.fun page may take a little time to index the new token.</p>`);
 }catch(e){
  const submitted=!!e.signature||!!e.submissionUnknown;
  if(submitted){saveLaunch(prepared,{signature:e.signature,status:e.code==='TRANSACTION_FAILED'?'failed':e.submissionUnknown?'submission unknown':'pending'});state.prepared=null;}
  if($('#sign-status'))$('#sign-status').innerHTML=esc(e.message)+(e.signature?`<br><a href="https://solscan.io/tx/${esc(e.signature)}" target="_blank" rel="noopener">Check submitted transaction ↗</a>`:'')+(submitted?`<br><a href="#/mine" data-action="close-modal">Open All creations to check status ↗</a>`:'');
  button.disabled=submitted;
 }
}
function download(name,data,type='text/html'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500)}
function exportCurrent(project=false){if(!state.current)return;const slug=state.current.name.toLowerCase().replace(/[^a-z0-9]+/g,'-');download(slug+(project?'.grokbots.json':'.html'),project?JSON.stringify({format:'grokbots-v1',...state.current},null,2):state.current.html,project?'application/json':'text/html');toast('Your creation is exported.')}
function desktopModal(){modal(`<div class="modal-eyebrow">YOUR STUDIO, MEET YOUR DESKTOP</div><h2>A companion connection.</h2><p>Run the included desktop bridge on this Windows computer, then paste the pairing code it prints. The bridge only detects and opens the installed Grok Bot app. It does not access your chats or wallet.</p><p class="inline-code">node desktop-bridge.mjs</p><form id="desktop-form"><label class="field">Pairing code<input name="token" type="password" autocomplete="off" placeholder="Paste the code from your bridge terminal" required></label><button class="btn primary" type="submit">${icon('link')}Pair this visit</button></form><div id="desktop-status" class="notice ${state.desktop?'good':''}">${state.desktop?'Paired. You can open Grok Bot below.':'Not connected yet. The bridge listens on 127.0.0.1:4318 only.'}</div>${state.desktop?'<button class="btn" data-action="open-desktop">Open Grok Bot ↗</button>':''}<p>Grok chat and generation in this website use your xAI API key separately. Browsers may ask you to allow access to the local companion.</p>`)}
async function desktopRequest(path,token=state.desktop){const response=await fetch('http://127.0.0.1:4318'+path,{method:path==='/open'?'POST':'GET',headers:{Authorization:'Bearer '+token},signal:AbortSignal.timeout(5000)});const d=await response.json();if(!response.ok)throw Error(d.error||'Desktop bridge is unavailable');return d;}
document.addEventListener('submit',async e=>{const form=e.target;e.preventDefault();if(form.id==='quick-build'){state.prompt=new FormData(form).get('idea');state.current=null;location.hash='/build'}else if(form.id==='build-form')await startBuild(form);else if(form.id==='chat-form')await sendChat(form);else if(form.id==='launch-form')await prepareToken(form);else if(form.id==='key-form'){state.key=new FormData(form).get('key').trim();closeModal();toast('xAI key set for this visit. Reloading clears it.')}else if(form.id==='desktop-form'){const token=new FormData(form).get('token').trim();try{const d=await desktopRequest('/status',token);state.desktop=token;$('#desktop-label').textContent=d.running?'Grok Bot is running':'Paired · Ready to open';desktopModal();toast('Desktop companion paired.')}catch(e){$('#desktop-status').textContent='Could not pair. Start the bridge and check the code. '+e.message;}}});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;const {action,id}=button.dataset;try{
 if(action==='skip-main'){e.preventDefault();$('#main').focus();}else if(action==='close-modal')closeModal();else if(action==='menu')document.body.classList.toggle('menu-open');else if(action==='settings')settings();else if(action==='wallet')walletModal();else if(action==='connect-wallet')await connectWallet(button.dataset.provider);else if(action==='disconnect'){await state.wallet?.disconnect();walletReset();closeModal();toast('Wallet disconnected.')}else if(action==='copy-wallet'){await navigator.clipboard.writeText(state.wallet.publicKey.toString());toast('Wallet address copied.')}else if(action==='filter'){state.filter=button.dataset.filter;$$('[data-action="filter"]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',b===button)});$('#gallery-cards').innerHTML=filteredCards();drawIcons();}else if(action==='save'){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();button.classList.toggle('saved',state.saved.includes(id));toast(state.saved.includes(id)?'Saved for a little later.':'Bookmark removed.');}else if(action==='pick-bot'){if(state.chatBusy){toast('Wait for the current response to finish.');return}location.hash='/room/'+id;}else if(action==='clear-chat'){if(state.chatBusy)return;state.chats[state.activeBot]=[];$('#chat-history').innerHTML=chatMessages();}else if(action==='preset'){const t=templates.find(t=>t.id===id);const f=$('#build-form');f.elements.name.value=t.name;f.elements.prompt.value=t.prompt;f.elements.mode.value='starter';f.elements.starter.value=id;$('#starter-field').classList.remove('hidden');}else if(action==='source'){if(state.current){state.source=!state.source;showPreview(state.current.html)}else toast('Build or open a creation to inspect its source.');}else if(action==='viewport'){const frame=$('.preview-frame');if(frame)frame.style.width=button.dataset.width;}else if(action==='export-current')exportCurrent();else if(action==='export-project')exportCurrent(true);else if(action==='launch-current'){if(state.current?.starter){const copy={...state.current,id:crypto.randomUUID(),starter:false,created:Date.now(),name:state.current.name};state.builds.unshift(copy);state.current=copy;persist()}await syncProject(state.current);location.hash='/launch';}else if(action==='remix'){const b=getBuild(id);state.current={...b};state.prompt=b.prompt||b.description;location.hash='/build';}else if(action==='share'){const b=getBuild(id);if(b.starter||b.cloud&&b.published){await navigator.clipboard.writeText(location.origin+'/#/creation/'+id);toast('Project link copied. Site access settings still apply.')}else{exportCurrent(true);toast('Project exported. Share the JSON so others can import it.');}}else if(action==='delete'){modal(`<div class="modal-eyebrow">LOCAL DRAFT</div><h2>Remove this creation?</h2><p>Export a copy first if you want to keep the source. This removes the cloud project and local backup. It does not change any token already launched on Solana.</p><div class="modal-actions"><button class="btn" data-action="export-project">Export project</button><button class="btn danger" data-action="confirm-delete" data-id="${id}">Remove creation</button></div>`);}else if(action==='confirm-delete'){if(state.cloudReady){const r=await fetch('/api/projects/'+encodeURIComponent(id),{method:'DELETE'});if(!r.ok)throw Error('Could not remove cloud project.');state.cloud=state.cloud.filter(x=>x.id!==id);}state.builds=state.builds.filter(x=>x.id!==id);persist();state.current=null;closeModal();location.hash='/mine';}else if(action==='clear-key'){state.key='';settings();toast('Session API key cleared.');}else if(action==='sign-launch')await submitLaunch(button);else if(action==='check-launch')await checkSavedLaunch(button);else if(action==='copy-token-ca'){await navigator.clipboard.writeText(button.dataset.id);toast('Contract address copied.');}else if(action==='load-launches'){button.disabled=true;await loadPublicLaunches(true);route();}else if(action==='desktop')desktopModal();else if(action==='open-desktop'){await desktopRequest('/open');toast('Grok Bot opened on your desktop.');}else if(action==='publish-project'){const b=getBuild(id);if(!b||b.owned===false)throw Error('Only your own creations can be shared.');const wasPublic=b.cloud&&b.published;await syncProject({...b,published:!wasPublic},true);toast(wasPublic?'Creation is now private.':'Shared in All creations and on the homepage.');route();}else if(action==='import')$('#import-file').click();
 }catch(err){toast(err.message||'Something interrupted that action.')}});
document.addEventListener('input',e=>{if(e.target.id==='gallery-search'){state.query=e.target.value;$('#gallery-cards').innerHTML=filteredCards();drawIcons()}if(e.target.id==='token-name')$('#preview-token-name').textContent=e.target.value||'Your next big idea';if(e.target.id==='token-symbol')$('#preview-token-symbol').textContent='$'+(e.target.value.toUpperCase()||'YOURTICKER');if(e.target.id==='token-description')$('#preview-token-desc').textContent=e.target.value||'A little identity goes a long way.';});
document.addEventListener('change',async e=>{if(e.target.name==='mode')$('#starter-field')?.classList.toggle('hidden',e.target.value!=='starter');if(e.target.id==='token-image'){const file=e.target.files[0];if(!file)return;if(file.size>5000000){toast('Choose an image below 5 MB.');e.target.value='';return}const img=document.createElement('img');img.alt='Your token artwork';const url=URL.createObjectURL(file);img.onload=()=>URL.revokeObjectURL(url);img.src=url;$('#token-art').replaceChildren(img);}if(e.target.name==='buildId'){const b=state.builds.find(x=>x.id===e.target.value);if(b){$('#token-name').value=b.name.slice(0,32);$('#token-description').value=b.description;$('#preview-token-name').textContent=b.name;$('#preview-token-desc').textContent=b.description;}}if(e.target.id==='import-file'){try{const file=e.target.files[0];if(!file||file.size>3000000)throw Error('Choose a project JSON file below 3 MB.');const d=JSON.parse(await file.text());if(d.format!=='grokbots-v1'||typeof d.html!=='string'||typeof d.name!=='string')throw Error('This is not a Grokbots project export.');const b={id:crypto.randomUUID(),name:d.name.slice(0,60),description:String(d.description||'Imported creation').slice(0,170),prompt:String(d.prompt||''),html:d.html,art:['orbit','grid','lavender','orange','dark','pink'].includes(d.art)?d.art:'orbit',category:['Tools','Bots','Games'].includes(d.category)?d.category:'Tools',created:Date.now()};state.builds.unshift(b);persist();await syncProject(b);closeModal();location.hash='/creation/'+b.id;toast('Project imported.')}catch(err){toast(err.message)}}});
document.addEventListener('keydown',e=>{if(e.key==='b'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open&&!e.metaKey&&!e.ctrlKey)location.hash='/build';if(e.key==='Enter'&&!e.shiftKey&&e.target.matches('#chat-form textarea')){e.preventDefault();$('#chat-form').requestSubmit();}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
async function syncProject(b,required=false){if(!b||b.starter||b.owned===false)return;try{const r=await fetch('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});const d=await r.json();if(!r.ok)throw Error(d.error||'Cloud save failed');b.cloud=true;b.owned=true;state.cloudReady=true;const i=state.cloud.findIndex(x=>x.id===b.id);if(i<0)state.cloud.unshift(b);else state.cloud[i]=b;persist();return b;}catch(e){if(required)throw e;log('Cloud save unavailable. Your local copy is preserved.');toast(state.signedIn?'Saved locally. Cloud sync is unavailable right now.':'Saved locally. Sign in, then choose Share to All creations to list it for everyone.');}}
async function loadCloud(){try{const r=await fetch('/api/projects');if(!r.ok)return;const d=await r.json();state.cloud=(d.projects||[]).map(b=>({...b,cloud:true}));state.cloudReady=true;const own=state.cloud.filter(b=>b.owned);for(const b of own){const i=state.builds.findIndex(x=>x.id===b.id);if(i<0)state.builds.unshift(b);else state.builds[i]=b;}persist();if(!state.building&&!$('#modal').open)route();}catch{}}
window.addEventListener('hashchange',route);persist();route();fetch('/api/status').then(r=>r.json()).then(d=>{state.configured=d.grokConfigured;state.signedIn=d.signedIn;const account=$('#account-link');if(account){account.textContent=d.signedIn?'Sign out':'Sign in';account.href=d.signedIn?'/signout-with-chatgpt?return_to=%2F':'/signin-with-chatgpt?return_to=%2F';}}).catch(()=>{});

loadCloud();

document.addEventListener('input',e=>{if(e.target.id==='dev-buy-enabled'||e.target.id==='dev-buy-sol'){const enabled=$('#dev-buy-enabled')?.checked;$('#dev-buy-sol').disabled=!enabled;$('#dev-buy-sol').required=enabled;$('#preview-dev-buy').textContent=enabled?($('#dev-buy-sol').value||'0')+' SOL':'Off';}});

let communityRefreshBusy=false;setInterval(async()=>{if(communityRefreshBusy||document.hidden||state.building||$('#modal').open||!['#/discover','#/mine',''].includes(location.hash))return;communityRefreshBusy=true;try{const r=await fetch('/api/projects');if(!r.ok)return;const d=await r.json();const next=(d.projects||[]).map(b=>({...b,cloud:true}));if(JSON.stringify(next)!==JSON.stringify(state.cloud)){state.cloud=next;state.cloudReady=true;persist();if(location.hash==='#/mine'){const scrollY=window.scrollY;route();window.scrollTo(0,scrollY);}else{const box=$('.community-box');if(box)box.outerHTML=communityBox();if($('#gallery-cards'))$('#gallery-cards').innerHTML=filteredCards();drawIcons();}}}catch{}finally{communityRefreshBusy=false;}},30000);

let launchFeedBusy=false;async function loadPublicLaunches(append=false){if(launchFeedBusy)return;launchFeedBusy=true;try{const offset=append?(state.launchNext||0):0;const r=await fetch('/api/launches?limit=100&offset='+offset);if(!r.ok)throw Error('Launch gallery unavailable');const d=await r.json();state.sharedLaunches=mergePublicLaunches(state.sharedLaunches,d.launches||[]);state.launchTotal=d.total||0;state.launchNext=d.nextOffset;state.launchFeedReady=true;$('#my-count').textContent=allCreationsEntries(state.cloud,state.builds).length+state.launchTotal;if(!state.building&&!$('#modal').open){if(location.hash==='#/mine'){const y=window.scrollY;route();window.scrollTo(0,y);}else{const box=$('.community-box');if(box)box.outerHTML=communityBox();if($('#gallery-cards'))$('#gallery-cards').innerHTML=filteredCards();drawIcons();}}}catch{if(location.hash==='#/mine')toast('The launch gallery is temporarily unavailable. Refresh shortly.');}finally{launchFeedBusy=false;}}
let launchSyncing=new Set();async function syncLaunchRecord(record){if(!record.receipt||launchSyncing.has(record.mint))return false;launchSyncing.add(record.mint);try{const r=await fetch('/api/launches/confirm',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mint:record.mint,signature:record.signature,receipt:record.receipt})});const d=await r.json();if(!r.ok)throw Error(d.error||'Public launch sync unavailable');record.gallerySaved=true;persist();await loadPublicLaunches();return true;}catch(e){record.gallerySaved=false;persist();toast('Your launch is confirmed. Gallery sync is pending; use Check status to retry.');return false;}finally{launchSyncing.delete(record.mint);}}
document.addEventListener('error',e=>{const img=e.target;if(img?.classList?.contains('token-pfp-image')){img.hidden=true;const fallback=img.parentElement.querySelector('.token-pfp-fallback');if(fallback)fallback.hidden=false;}},true);
loadPublicLaunches();for(const record of state.launches)if(record.status==='confirmed'&&record.receipt&&!record.gallerySaved)void syncLaunchRecord(record);
setInterval(()=>{if(!document.hidden&&!state.building&&!$('#modal').open&&['#/mine','#/discover',''].includes(location.hash))void loadPublicLaunches();},30000);
